def transform(grid):
    h, w = len(grid), len(grid[0])
    directions = {
        "row": lambda r, c: r,
        "col": lambda r, c: c,
        "sum": lambda r, c: r + c,
        "diff": lambda r, c: c - r,
    }

    best_name = None
    best_score = -1
    best_groups = None

    for name, key_fn in directions.items():
        groups = {}
        for r in range(h):
            for c in range(w):
                if grid[r][c] != 0:
                    groups.setdefault(key_fn(r, c), []).append(grid[r][c])

        score = sum(len(vals) ** 2 for vals in groups.values()
                    if len(vals) >= 2 and len(set(vals)) == 1)
        if score > best_score:
            best_name, best_score, best_groups = name, score, groups

    observations = {
        k: vals[0] for k, vals in best_groups.items()
        if len(set(vals)) == 1
    }

    lo, hi = min(observations), max(observations)
    period = hi - lo + 1
    for p in range(1, hi - lo + 2):
        residues = {}
        valid = True
        for k, color in observations.items():
            rem = k % p
            if rem in residues and residues[rem] != color:
                valid = False
                break
            residues[rem] = color
        if valid:
            period = p
            break

    pattern = {}
    for k, color in observations.items():
        pattern[k % period] = color

    for rem in range(period):
        if rem not in pattern:
            opposite = (rem + period // 2) % period
            if period % 2 == 0 and opposite in pattern:
                pattern[rem] = pattern[opposite]
            else:
                known = min(pattern, key=lambda x: min((rem - x) % period,
                                                       (x - rem) % period))
                pattern[rem] = pattern[known]

    key_fn = directions[best_name]
    return [[pattern[key_fn(r, c) % period] for c in range(w)]
            for r in range(h)]
